{
  "name": "aigradelab",
  "version": "1.0.0",
  "private": true,
  "scripts": {
    "dev": "next dev",
    "build": "next build",
    "start": "next start"
  },
  "dependencies": {
    "next": "^15.0.0",
    "react": "^19.0.0",
    "react-dom": "^19.0.0",
    "@vercel/analytics": "^1.0.0"
  },
  "devDependencies": {
    "typescript": "^5.8.2",
    "@types/node": "^20.0.0",
    "@types/react": "^19.0.0",
    "@types/react-dom": "^19.0.0"
  }
}

import { notFound } from 'next/navigation';
import { posts } from '../../../content/posts';
import GradeBadge from '../../../components/GradeBadge';
import ScoreCard from '../../../components/ScoreCard';
import type { Metadata } from 'next';

type Props = { params: Promise<{ slug: string }> };

export async function generateStaticParams() {
  return posts.map((p) => ({ slug: p.slug }));
}

export async function generateMetadata({ params }: Props): Promise<Metadata> {
  const { slug } = await params;
  const post = posts.find((p) => p.slug === slug);
  if (!post) return {};
  const gradeText = post.grade ? ` [Grade: ${post.grade}]` : '';
  return {
    title: `${post.title}${gradeText}`,
    description: post.description,
    openGraph: {
      title: `${post.title}${gradeText}`,
      description: post.description,
      type: 'article',
      publishedTime: post.date,
    },
  };
}

export default async function ArticlePage({ params }: Props) {
  const { slug } = await params;
  const post = posts.find((p) => p.slug === slug);
  if (!post) notFound();

  const jsonLd = {
    '@context': 'https://schema.org',
    '@type': 'Article',
    headline: post.title,
    description: post.description,
    datePublished: post.date,
    dateModified: post.lastTested || post.date,
    author: { '@type': 'Organization', name: 'AIGradeLab', url: 'https://aigradelab.com' },
    publisher: { '@type': 'Organization', name: 'AIGradeLab', url: 'https://aigradelab.com' },
    ...(post.grade && post.scores ? {
      review: {
        '@type': 'Review',
        reviewRating: {
          '@type': 'Rating',
          ratingValue: ((post.scores.ux + post.scores.quality + post.scores.value + post.scores.integration + post.scores.support) / 5).toFixed(1),
          bestRating: '10',
          worstRating: '0',
        },
        itemReviewed: { '@type': 'SoftwareApplication', name: post.toolName || post.title },
      },
    } : {}),
  };

  return (
    <>
      <script
        type="application/ld+json"
        dangerouslySetInnerHTML={{ __html: JSON.stringify(jsonLd) }}
      />

      <div className="container">
        <div className="article-header">
          <span className="article-card-category">{post.category}</span>
          <h1>{post.title}</h1>

          <div className="article-card-meta" style={{ marginTop: '12px' }}>
            <span>{post.date}</span>
            <span>{post.readTime}</span>
            {post.lastTested && <span className="last-tested">Tested {post.lastTested}</span>}
          </div>

          {post.grade && (
            <div className="article-verdict">
              <GradeBadge grade={post.grade} size="xl" />
              <div className="article-verdict-text">
                <strong>Our Grade: {post.grade}</strong>
                <p style={{ fontSize: '0.9rem', color: 'var(--text-muted)', marginTop: '2px' }}>
                  Based on hands-on testing across 5 criteria
                </p>
              </div>
            </div>
          )}

          <ScoreCard scores={post.scores} />
        </div>

        <div className="article-body" dangerouslySetInnerHTML={{ __html: post.content }} />

        {post.affiliateUrl && (
          <div style={{ textAlign: 'center', padding: '20px 0 40px', maxWidth: '760px', margin: '0 auto' }}>
            <a href={post.affiliateUrl} target="_blank" rel="noopener sponsored" style={{
              display: 'inline-block',
              background: 'var(--accent)',
              color: '#fff',
              padding: '14px 36px',
              borderRadius: '8px',
              fontWeight: 600,
              fontSize: '1rem',
            }}>
              Try {post.toolName || 'this tool'} →
            </a>
          </div>
        )}

        <div className="tck-promo" style={{ maxWidth: '760px', margin: '0 auto 40px' }}>
          <div className="tck-promo-text">
            <strong>Need free tools?</strong>
            <p>ToolCraftKit has 49+ free web tools for productivity, text processing, and more.</p>
          </div>
          <a href="https://toolcraftkit.com" target="_blank" rel="noopener">Try Free Tools</a>
        </div>

        <div className="newsletter-cta" style={{ maxWidth: '760px', margin: '0 auto' }}>
          <h3>Get graded reviews in your inbox</h3>
          <p>New AI tool grades every week. No spam, no fluff — just honest scores.</p>
          <a href="#" className="cta-btn">Subscribe Free</a>
        </div>
      </div>
    </>
  );
}

import { posts } from '../../content/posts';
import ArticleCard from '../../components/ArticleCard';
import type { Metadata } from 'next';

export const metadata: Metadata = {
  title: 'All Graded AI Tool Reviews',
  description: 'Browse all AI tool reviews with transparent grades from A+ to F. Every tool tested across 5 criteria.',
};

export default function BlogPage() {
  return (
    <div className="container" style={{ paddingTop: '40px' }}>
      <h1 style={{ fontSize: '2rem', fontWeight: 800, marginBottom: '8px' }}>All Graded Reviews</h1>
      <p style={{ color: 'var(--text-secondary)', marginBottom: '24px', fontSize: '1.02rem' }}>
        Every tool tested, scored, and graded. No sponsored rankings.
      </p>

      {posts.length > 0 ? (
        <div className="articles-grid">
          {posts.map((post) => (
            <ArticleCard key={post.slug} post={post} />
          ))}
        </div>
      ) : (
        <div style={{ textAlign: 'center', padding: '80px 0', color: 'var(--text-muted)' }}>
          <p style={{ fontSize: '1.1rem' }}>Reviews are being prepared in the lab.</p>
        </div>
      )}
    </div>
  );
}

@import url('https://fonts.googleapis.com/css2?family=Inter:wght@400;500;600;700;800;900&family=JetBrains+Mono:wght@500&display=swap');

:root {
  --font-body: 'Inter', -apple-system, BlinkMacSystemFont, sans-serif;
  --font-mono: 'JetBrains Mono', monospace;

  /* Base palette */
  --bg-primary: #0A0A0F;
  --bg-secondary: #12121A;
  --bg-card: #1A1A25;
  --bg-card-hover: #22222F;
  --border: #2A2A3A;
  --border-light: #3A3A4A;

  --text-primary: #F0F0F5;
  --text-secondary: #A0A0B8;
  --text-muted: #6A6A82;

  /* Grade colors */
  --grade-aplus: #10B981;
  --grade-a: #34D399;
  --grade-bplus: #60A5FA;
  --grade-b: #93C5FD;
  --grade-c: #FBBF24;
  --grade-d: #F97316;
  --grade-f: #EF4444;

  /* Accent */
  --accent: #8B5CF6;
  --accent-hover: #7C3AED;
  --accent-soft: rgba(139, 92, 246, 0.12);

  --max-width: 1120px;
  --radius: 10px;
}

* { margin: 0; padding: 0; box-sizing: border-box; }

html { scroll-behavior: smooth; }

body {
  font-family: var(--font-body);
  background: var(--bg-primary);
  color: var(--text-primary);
  line-height: 1.65;
  -webkit-font-smoothing: antialiased;
}

a { color: var(--accent); text-decoration: none; transition: color 0.15s; }
a:hover { color: var(--accent-hover); }

img { max-width: 100%; display: block; }

/* Layout */
.container { max-width: var(--max-width); margin: 0 auto; padding: 0 24px; }

/* Header */
.site-header {
  border-bottom: 1px solid var(--border);
  padding: 18px 0;
  position: sticky;
  top: 0;
  background: rgba(10, 10, 15, 0.92);
  backdrop-filter: blur(12px);
  z-index: 100;
}
.site-header .container {
  display: flex;
  align-items: center;
  justify-content: space-between;
}
.logo {
  font-weight: 800;
  font-size: 1.25rem;
  color: var(--text-primary);
  display: flex;
  align-items: center;
  gap: 8px;
}
.logo-mark {
  background: var(--accent);
  color: #fff;
  font-weight: 900;
  font-size: 0.75rem;
  padding: 3px 7px;
  border-radius: 5px;
  font-family: var(--font-mono);
  letter-spacing: 0.5px;
}
.nav-links { display: flex; gap: 28px; align-items: center; }
.nav-links a {
  color: var(--text-secondary);
  font-size: 0.9rem;
  font-weight: 500;
  transition: color 0.15s;
}
.nav-links a:hover { color: var(--text-primary); }

/* Hero */
.hero {
  padding: 80px 0 60px;
  text-align: center;
}
.hero h1 {
  font-size: 3rem;
  font-weight: 900;
  line-height: 1.15;
  max-width: 720px;
  margin: 0 auto 20px;
  letter-spacing: -0.02em;
}
.hero h1 .highlight {
  background: linear-gradient(135deg, var(--accent), var(--grade-aplus));
  -webkit-background-clip: text;
  -webkit-text-fill-color: transparent;
  background-clip: text;
}
.hero p {
  font-size: 1.15rem;
  color: var(--text-secondary);
  max-width: 560px;
  margin: 0 auto 36px;
}

/* Grade Badge */
.grade-badge {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  font-family: var(--font-mono);
  font-weight: 700;
  border-radius: 8px;
  line-height: 1;
}
.grade-badge.size-sm { font-size: 0.75rem; padding: 4px 8px; }
.grade-badge.size-md { font-size: 1rem; padding: 6px 12px; }
.grade-badge.size-lg { font-size: 1.5rem; padding: 10px 18px; }
.grade-badge.size-xl { font-size: 2.5rem; padding: 14px 24px; }

.grade-badge.grade-aplus { background: rgba(16,185,129,0.15); color: var(--grade-aplus); border: 1px solid rgba(16,185,129,0.3); }
.grade-badge.grade-a { background: rgba(52,211,153,0.15); color: var(--grade-a); border: 1px solid rgba(52,211,153,0.3); }
.grade-badge.grade-bplus { background: rgba(96,165,250,0.15); color: var(--grade-bplus); border: 1px solid rgba(96,165,250,0.3); }
.grade-badge.grade-b { background: rgba(147,197,253,0.15); color: var(--grade-b); border: 1px solid rgba(147,197,253,0.3); }
.grade-badge.grade-c { background: rgba(251,191,36,0.15); color: var(--grade-c); border: 1px solid rgba(251,191,36,0.3); }
.grade-badge.grade-d { background: rgba(249,115,22,0.15); color: var(--grade-d); border: 1px solid rgba(249,115,22,0.3); }
.grade-badge.grade-f { background: rgba(239,68,68,0.15); color: var(--grade-f); border: 1px solid rgba(239,68,68,0.3); }

/* Score Card */
.score-card {
  background: var(--bg-card);
  border: 1px solid var(--border);
  border-radius: var(--radius);
  padding: 28px;
  margin: 28px 0;
}
.score-card h3 {
  font-size: 0.85rem;
  text-transform: uppercase;
  letter-spacing: 0.06em;
  color: var(--text-muted);
  margin-bottom: 20px;
  font-weight: 600;
}
.score-row {
  display: flex;
  align-items: center;
  gap: 14px;
  margin-bottom: 14px;
}
.score-label {
  width: 140px;
  font-size: 0.9rem;
  color: var(--text-secondary);
  flex-shrink: 0;
}
.score-bar-bg {
  flex: 1;
  height: 8px;
  background: var(--bg-primary);
  border-radius: 4px;
  overflow: hidden;
}
.score-bar-fill {
  height: 100%;
  border-radius: 4px;
  transition: width 0.6s ease;
}
.score-value {
  width: 36px;
  text-align: right;
  font-family: var(--font-mono);
  font-size: 0.9rem;
  font-weight: 600;
  flex-shrink: 0;
}

/* Article Cards */
.articles-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(340px, 1fr));
  gap: 20px;
  padding: 40px 0;
}
.article-card {
  background: var(--bg-card);
  border: 1px solid var(--border);
  border-radius: var(--radius);
  padding: 24px;
  transition: border-color 0.2s, background 0.2s;
  display: flex;
  flex-direction: column;
}
.article-card:hover {
  border-color: var(--border-light);
  background: var(--bg-card-hover);
}
.article-card-top {
  display: flex;
  justify-content: space-between;
  align-items: flex-start;
  margin-bottom: 14px;
}
.article-card-category {
  font-size: 0.75rem;
  color: var(--accent);
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.04em;
}
.article-card h2 {
  font-size: 1.1rem;
  font-weight: 700;
  line-height: 1.35;
  margin-bottom: 10px;
  color: var(--text-primary);
}
.article-card h2 a { color: inherit; }
.article-card h2 a:hover { color: var(--accent); }
.article-card p {
  font-size: 0.9rem;
  color: var(--text-secondary);
  margin-bottom: 16px;
  flex: 1;
}
.article-card-meta {
  display: flex;
  gap: 16px;
  font-size: 0.8rem;
  color: var(--text-muted);
}

/* Article Page */
.article-header {
  padding: 60px 0 40px;
  max-width: 760px;
  margin: 0 auto;
}
.article-header .article-card-category { margin-bottom: 16px; display: inline-block; }
.article-header h1 {
  font-size: 2.2rem;
  font-weight: 800;
  line-height: 1.2;
  margin-bottom: 16px;
  letter-spacing: -0.01em;
}
.article-verdict {
  display: flex;
  align-items: center;
  gap: 16px;
  padding: 20px 0;
  border-top: 1px solid var(--border);
  border-bottom: 1px solid var(--border);
  margin: 24px 0;
}
.article-verdict-text {
  font-size: 1.05rem;
  color: var(--text-secondary);
}
.article-body {
  max-width: 760px;
  margin: 0 auto;
  padding-bottom: 60px;
}
.article-body h2 {
  font-size: 1.4rem;
  font-weight: 700;
  margin: 36px 0 14px;
  color: var(--text-primary);
}
.article-body h3 {
  font-size: 1.15rem;
  font-weight: 600;
  margin: 28px 0 12px;
}
.article-body p {
  margin-bottom: 16px;
  color: var(--text-secondary);
  font-size: 1.02rem;
}
.article-body ul, .article-body ol {
  margin: 0 0 16px 20px;
  color: var(--text-secondary);
}
.article-body li { margin-bottom: 6px; }
.article-body strong { color: var(--text-primary); }

/* Last Tested Badge */
.last-tested {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  font-size: 0.8rem;
  color: var(--grade-aplus);
  background: rgba(16,185,129,0.08);
  padding: 4px 10px;
  border-radius: 20px;
  font-weight: 500;
}

/* Newsletter CTA */
.newsletter-cta {
  background: var(--bg-card);
  border: 1px solid var(--border);
  border-radius: var(--radius);
  padding: 36px;
  text-align: center;
  margin: 48px 0;
}
.newsletter-cta h3 {
  font-size: 1.3rem;
  font-weight: 700;
  margin-bottom: 8px;
}
.newsletter-cta p {
  color: var(--text-secondary);
  margin-bottom: 20px;
  font-size: 0.95rem;
}
.newsletter-cta .cta-btn {
  display: inline-block;
  background: var(--accent);
  color: #fff;
  padding: 12px 28px;
  border-radius: 8px;
  font-weight: 600;
  font-size: 0.95rem;
  transition: background 0.15s;
}
.newsletter-cta .cta-btn:hover { background: var(--accent-hover); color: #fff; }

/* ToolCraftKit Promo */
.tck-promo {
  background: linear-gradient(135deg, rgba(139,92,246,0.08), rgba(16,185,129,0.08));
  border: 1px solid var(--border);
  border-radius: var(--radius);
  padding: 20px 24px;
  display: flex;
  align-items: center;
  gap: 16px;
  margin: 32px 0;
}
.tck-promo-text { flex: 1; }
.tck-promo-text strong { font-size: 0.95rem; }
.tck-promo-text p { font-size: 0.85rem; color: var(--text-secondary); margin: 4px 0 0; }
.tck-promo a {
  background: var(--accent);
  color: #fff;
  padding: 8px 18px;
  border-radius: 6px;
  font-weight: 600;
  font-size: 0.85rem;
  white-space: nowrap;
}

/* Methodology page */
.methodology { max-width: 760px; margin: 0 auto; padding: 60px 0; }
.methodology h1 { font-size: 2rem; font-weight: 800; margin-bottom: 24px; }
.methodology h2 { font-size: 1.3rem; font-weight: 700; margin: 36px 0 14px; }
.methodology p { color: var(--text-secondary); margin-bottom: 16px; font-size: 1.02rem; }

/* Category Filter */
.category-filter {
  display: flex;
  gap: 10px;
  flex-wrap: wrap;
  padding: 20px 0;
}
.category-filter button {
  background: var(--bg-card);
  border: 1px solid var(--border);
  color: var(--text-secondary);
  padding: 8px 16px;
  border-radius: 20px;
  font-size: 0.85rem;
  font-weight: 500;
  cursor: pointer;
  transition: all 0.15s;
  font-family: var(--font-body);
}
.category-filter button:hover,
.category-filter button.active {
  border-color: var(--accent);
  color: var(--accent);
  background: var(--accent-soft);
}

/* Footer */
.site-footer {
  border-top: 1px solid var(--border);
  padding: 40px 0;
  margin-top: 60px;
}
.footer-inner {
  display: flex;
  justify-content: space-between;
  align-items: center;
  flex-wrap: wrap;
  gap: 16px;
}
.footer-inner p { color: var(--text-muted); font-size: 0.85rem; }
.footer-links { display: flex; gap: 20px; }
.footer-links a { color: var(--text-muted); font-size: 0.85rem; }
.footer-links a:hover { color: var(--text-secondary); }

/* Responsive */
@media (max-width: 768px) {
  .hero h1 { font-size: 2rem; }
  .articles-grid { grid-template-columns: 1fr; }
  .nav-links { gap: 16px; }
  .nav-links a { font-size: 0.8rem; }
  .article-header h1 { font-size: 1.7rem; }
  .score-label { width: 100px; }
  .tck-promo { flex-direction: column; text-align: center; }
}

/* ===== REDESIGNED HOMEPAGE STYLES ===== */

/* Hero redesign */
.hero {
  position: relative;
  padding: 100px 0 80px;
  text-align: left;
  overflow: hidden;
}
.hero-glow {
  position: absolute;
  top: -120px;
  right: -80px;
  width: 500px;
  height: 500px;
  background: radial-gradient(circle, rgba(139,92,246,0.15) 0%, transparent 70%);
  pointer-events: none;
}
.hero-inner {
  display: flex;
  align-items: center;
  gap: 60px;
}
.hero-text { flex: 1; }
.hero-visual { flex-shrink: 0; }

.hero-pill {
  display: inline-block;
  font-size: 0.8rem;
  font-weight: 600;
  color: var(--accent);
  background: var(--accent-soft);
  padding: 6px 14px;
  border-radius: 20px;
  margin-bottom: 20px;
  letter-spacing: 0.02em;
}
.hero h1 {
  text-align: left;
  max-width: 600px;
  margin: 0 0 20px;
}
.hero p {
  text-align: left;
  max-width: 480px;
  margin: 0 0 32px;
}
.hero-actions {
  display: flex;
  gap: 12px;
  flex-wrap: wrap;
}
.btn-primary {
  display: inline-block;
  background: var(--accent);
  color: #fff !important;
  padding: 14px 28px;
  border-radius: 8px;
  font-weight: 600;
  font-size: 0.95rem;
  transition: background 0.15s, transform 0.1s;
}
.btn-primary:hover { background: var(--accent-hover); transform: translateY(-1px); }
.btn-secondary {
  display: inline-block;
  background: transparent;
  color: var(--text-secondary) !important;
  padding: 14px 28px;
  border-radius: 8px;
  font-weight: 600;
  font-size: 0.95rem;
  border: 1px solid var(--border);
  transition: border-color 0.15s, color 0.15s;
}
.btn-secondary:hover { border-color: var(--text-muted); color: var(--text-primary) !important; }

/* Hero card (score preview) */
.hero-card {
  width: 280px;
  background: var(--bg-card);
  border: 1px solid var(--border);
  border-radius: 14px;
  padding: 0;
  overflow: hidden;
  box-shadow: 0 20px 60px rgba(0,0,0,0.3), 0 0 0 1px rgba(139,92,246,0.08);
}
.hero-card-header {
  display: flex;
  gap: 6px;
  padding: 12px 16px;
  border-bottom: 1px solid var(--border);
}
.hero-card-dot {
  width: 10px;
  height: 10px;
  border-radius: 50%;
  background: var(--border-light);
}
.hero-card-dot:nth-child(1) { background: #EF4444; }
.hero-card-dot:nth-child(2) { background: #FBBF24; }
.hero-card-dot:nth-child(3) { background: #10B981; }
.hero-grade-display {
  text-align: center;
  padding: 24px 0 16px;
}
.hero-grade-letter {
  font-family: var(--font-mono);
  font-size: 3.5rem;
  font-weight: 900;
  color: var(--grade-aplus);
  text-shadow: 0 0 40px rgba(16,185,129,0.3);
}
.hero-card-bars { padding: 0 20px 20px; }
.hero-bar {
  display: flex;
  align-items: center;
  gap: 8px;
  margin-bottom: 8px;
}
.hero-bar-label {
  width: 52px;
  font-size: 0.7rem;
  color: var(--text-muted);
  flex-shrink: 0;
}
.hero-bar-track {
  flex: 1;
  height: 5px;
  background: var(--bg-primary);
  border-radius: 3px;
  overflow: hidden;
}
.hero-bar-fill {
  height: 100%;
  background: var(--grade-aplus);
  border-radius: 3px;
}
.hero-bar-val {
  width: 28px;
  text-align: right;
  font-family: var(--font-mono);
  font-size: 0.7rem;
  color: var(--grade-aplus);
  flex-shrink: 0;
}

/* Section styling */
.section-how, .section-criteria, .section-grades, .section-reviews {
  padding: 70px 0 30px;
}
.section-label {
  font-size: 0.8rem;
  font-weight: 600;
  color: var(--accent);
  text-transform: uppercase;
  letter-spacing: 0.06em;
  margin-bottom: 8px;
}
.section-title {
  font-size: 1.8rem;
  font-weight: 800;
  margin-bottom: 36px;
  letter-spacing: -0.01em;
}

/* Steps */
.steps-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 20px;
}
.step-card {
  background: var(--bg-card);
  border: 1px solid var(--border);
  border-radius: var(--radius);
  padding: 28px 24px;
  transition: border-color 0.2s;
}
.step-card:hover { border-color: var(--accent); }
.step-num {
  font-family: var(--font-mono);
  font-size: 2rem;
  font-weight: 700;
  color: var(--accent);
  opacity: 0.4;
  display: block;
  margin-bottom: 12px;
  line-height: 1;
}
.step-card h3 {
  font-size: 1.1rem;
  font-weight: 700;
  margin-bottom: 6px;
}
.step-card p {
  font-size: 0.9rem;
  color: var(--text-secondary);
  margin: 0;
}

/* Criteria */
.criteria-grid {
  display: flex;
  flex-wrap: wrap;
  gap: 14px;
}
.criteria-item {
  display: flex;
  align-items: center;
  gap: 12px;
  background: var(--bg-card);
  border: 1px solid var(--border);
  border-radius: var(--radius);
  padding: 16px 20px;
  flex: 1 1 200px;
  min-width: 200px;
  transition: border-color 0.2s;
}
.criteria-item:hover { border-color: var(--border-light); }
.criteria-icon { font-size: 1.4rem; flex-shrink: 0; }
.criteria-item strong { font-size: 0.9rem; display: block; }
.criteria-item p { font-size: 0.8rem; color: var(--text-muted); margin: 2px 0 0; }

/* Grade strip */
.grade-strip {
  display: flex;
  gap: 12px;
  justify-content: center;
  flex-wrap: wrap;
  margin-bottom: 20px;
}
.grade-chip {
  width: 72px;
  height: 72px;
  display: flex;
  align-items: center;
  justify-content: center;
  border-radius: 14px;
  background: color-mix(in srgb, var(--chip-color) 12%, transparent);
  border: 1px solid color-mix(in srgb, var(--chip-color) 25%, transparent);
  transition: transform 0.15s;
}
.grade-chip:hover { transform: scale(1.1); }
.grade-chip-letter {
  font-family: var(--font-mono);
  font-weight: 800;
  font-size: 1.5rem;
  color: var(--chip-color);
}
.grade-strip-sub {
  text-align: center;
  color: var(--text-muted);
  font-size: 0.9rem;
}
.section-grades { text-align: center; }

/* Empty state */
.empty-state {
  text-align: center;
  padding: 60px 20px;
  background: var(--bg-card);
  border: 1px solid var(--border);
  border-radius: var(--radius);
}
.empty-icon { font-size: 2.5rem; margin-bottom: 16px; }
.empty-title { font-size: 1.15rem; font-weight: 600; margin-bottom: 6px; color: var(--text-primary); }
.empty-sub { font-size: 0.9rem; color: var(--text-muted); max-width: 400px; margin: 0 auto; }

/* Newsletter badge */
.newsletter-badge {
  display: inline-block;
  font-size: 0.7rem;
  font-weight: 700;
  color: var(--grade-aplus);
  background: rgba(16,185,129,0.12);
  padding: 3px 10px;
  border-radius: 12px;
  margin-bottom: 12px;
  text-transform: uppercase;
  letter-spacing: 0.06em;
}

/* Responsive hero */
@media (max-width: 768px) {
  .hero { padding: 60px 0 50px; }
  .hero-inner { flex-direction: column; gap: 40px; }
  .hero h1 { text-align: center; font-size: 2rem; }
  .hero p { text-align: center; margin: 0 auto 28px; }
  .hero-pill { display: block; text-align: center; }
  .hero-actions { justify-content: center; }
  .hero-visual { display: flex; justify-content: center; }
  .hero-card { width: 260px; }
  .steps-grid { grid-template-columns: 1fr; }
  .section-title { font-size: 1.4rem; }
  .grade-chip { width: 56px; height: 56px; }
  .grade-chip-letter { font-size: 1.2rem; }
}

